PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT, display_name TEXT UNIQUE, avatar TEXT, bio TEXT, balance TEXT NOT NULL DEFAULT '10000', bank TEXT NOT NULL DEFAULT '0', level INTEGER NOT NULL DEFAULT 1, xp INTEGER NOT NULL DEFAULT 0, energy INTEGER NOT NULL DEFAULT 100, max_energy INTEGER NOT NULL DEFAULT 100, last_energy_regen INTEGER NOT NULL DEFAULT 0, pet_equipped TEXT, win_streak INTEGER NOT NULL DEFAULT 0, max_win_streak INTEGER NOT NULL DEFAULT 0, login_streak INTEGER NOT NULL DEFAULT 1, max_login_streak INTEGER NOT NULL DEFAULT 1, total_wins INTEGER NOT NULL DEFAULT 0, total_losses INTEGER NOT NULL DEFAULT 0, total_bets INTEGER NOT NULL DEFAULT 0, total_wagered TEXT NOT NULL DEFAULT '0', total_won TEXT NOT NULL DEFAULT '0', biggest_win TEXT NOT NULL DEFAULT '0', vip_tier INTEGER NOT NULL DEFAULT 0, clan_id INTEGER, banned INTEGER NOT NULL DEFAULT 0, ban_reason TEXT, muted INTEGER NOT NULL DEFAULT 0, muted_until INTEGER NOT NULL DEFAULT 0, win_rate_override REAL, last_daily INTEGER NOT NULL DEFAULT 0, last_login INTEGER NOT NULL DEFAULT 0, last_spin INTEGER NOT NULL DEFAULT 0, settings TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER);
CREATE TABLE IF NOT EXISTS pets (id TEXT PRIMARY KEY,name TEXT NOT NULL,icon TEXT NOT NULL,description TEXT,rarity TEXT NOT NULL,money_bonus REAL NOT NULL,xp_bonus REAL NOT NULL,price TEXT NOT NULL,hidden INTEGER NOT NULL DEFAULT 0,order_index INTEGER NOT NULL DEFAULT 0,max_level INTEGER NOT NULL DEFAULT 10,upgrade_cost_per_level TEXT NOT NULL DEFAULT '0',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS user_pets (user_id TEXT NOT NULL,pet_id TEXT NOT NULL,level INTEGER NOT NULL DEFAULT 1,equipped INTEGER NOT NULL DEFAULT 0,acquired_at INTEGER NOT NULL,PRIMARY KEY(user_id,pet_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(pet_id) REFERENCES pets(id));
CREATE TABLE IF NOT EXISTS bets (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,game TEXT NOT NULL,amount TEXT NOT NULL,result TEXT NOT NULL,payout TEXT NOT NULL DEFAULT '0',multiplier REAL NOT NULL DEFAULT 0,metadata TEXT,balance_after TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS transactions (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,type TEXT NOT NULL,amount TEXT NOT NULL,balance_before TEXT,balance_after TEXT,note TEXT,meta TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS quest_templates (id TEXT PRIMARY KEY,type TEXT NOT NULL,title TEXT NOT NULL,description TEXT,icon TEXT,target INTEGER NOT NULL,reward_money TEXT NOT NULL DEFAULT '0',reward_xp INTEGER NOT NULL DEFAULT 0,reward_item TEXT,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS user_quests (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,quest_id TEXT NOT NULL,progress INTEGER NOT NULL DEFAULT 0,completed INTEGER NOT NULL DEFAULT 0,claimed INTEGER NOT NULL DEFAULT 0,reset_at INTEGER,expires_at INTEGER,created_at INTEGER NOT NULL,UNIQUE(user_id,quest_id,reset_at));
CREATE TABLE IF NOT EXISTS achievement_templates (id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT,icon TEXT,category TEXT,target INTEGER,reward_money TEXT NOT NULL DEFAULT '0',reward_xp INTEGER NOT NULL DEFAULT 0,hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS user_achievements (user_id TEXT NOT NULL,achievement_id TEXT NOT NULL,progress INTEGER NOT NULL DEFAULT 0,unlocked_at INTEGER,claimed_at INTEGER,PRIMARY KEY(user_id,achievement_id));
CREATE TABLE IF NOT EXISTS coupons (code TEXT PRIMARY KEY,amount TEXT NOT NULL DEFAULT '0',pet_id TEXT,item_code TEXT,max_uses INTEGER NOT NULL DEFAULT 1,used_count INTEGER NOT NULL DEFAULT 0,created_by TEXT,expires_at INTEGER,active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS coupon_uses (coupon_code TEXT NOT NULL,user_id TEXT NOT NULL,used_at INTEGER NOT NULL,PRIMARY KEY(coupon_code,user_id));
CREATE TABLE IF NOT EXISTS jackpot (id INTEGER PRIMARY KEY CHECK(id=1),amount TEXT NOT NULL DEFAULT '1000000',last_winner TEXT,last_won_at INTEGER,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS jackpot_history (id INTEGER PRIMARY KEY AUTOINCREMENT,winner_id TEXT,amount TEXT,game TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS clans (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,tag TEXT,icon TEXT DEFAULT '🛡️',description TEXT,owner_id TEXT NOT NULL,level INTEGER NOT NULL DEFAULT 1,xp INTEGER NOT NULL DEFAULT 0,bank TEXT NOT NULL DEFAULT '0',member_count INTEGER NOT NULL DEFAULT 1,max_members INTEGER NOT NULL DEFAULT 20,public INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS clan_members (clan_id INTEGER NOT NULL,user_id TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'member',contribution TEXT NOT NULL DEFAULT '0',joined_at INTEGER NOT NULL,PRIMARY KEY(clan_id,user_id));
CREATE TABLE IF NOT EXISTS chat_channels (id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL DEFAULT 'public',clan_id INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS chat_messages (id INTEGER PRIMARY KEY AUTOINCREMENT,channel_id INTEGER NOT NULL,user_id TEXT NOT NULL,content TEXT NOT NULL,type TEXT NOT NULL DEFAULT 'text',reply_to INTEGER,meta TEXT,deleted INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,type TEXT NOT NULL,title TEXT,body TEXT,icon TEXT,read INTEGER NOT NULL DEFAULT 0,action_url TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS logs (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT,actor_id TEXT,action TEXT NOT NULL,target TEXT,meta TEXT,ip TEXT,level TEXT NOT NULL DEFAULT 'info',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS items (code TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT,icon TEXT,type TEXT NOT NULL,price TEXT NOT NULL DEFAULT '0',stackable INTEGER NOT NULL DEFAULT 1,effect TEXT,active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS inventory (user_id TEXT NOT NULL,item_code TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 1,acquired_at INTEGER NOT NULL,PRIMARY KEY(user_id,item_code));
CREATE TABLE IF NOT EXISTS trade_offers (id INTEGER PRIMARY KEY AUTOINCREMENT,from_user TEXT NOT NULL,to_user TEXT NOT NULL,offer_money TEXT NOT NULL DEFAULT '0',offer_items TEXT,offer_pets TEXT,request_money TEXT NOT NULL DEFAULT '0',request_items TEXT,request_pets TEXT,status TEXT NOT NULL DEFAULT 'pending',message TEXT,created_at INTEGER NOT NULL,expires_at INTEGER);
CREATE TABLE IF NOT EXISTS season_pass (user_id TEXT NOT NULL,season INTEGER NOT NULL,tier INTEGER NOT NULL DEFAULT 0,xp INTEGER NOT NULL DEFAULT 0,premium INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,season));
CREATE TABLE IF NOT EXISTS referrals (id INTEGER PRIMARY KEY AUTOINCREMENT,referrer_id TEXT NOT NULL,referred_id TEXT UNIQUE NOT NULL,level INTEGER NOT NULL DEFAULT 1,rewarded INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,description TEXT,icon TEXT,start_at INTEGER,end_at INTEGER,active INTEGER NOT NULL DEFAULT 0,config TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS system_settings (key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at INTEGER NOT NULL);

CREATE TABLE IF NOT EXISTS daily_rewards (user_id TEXT NOT NULL, day_index INTEGER NOT NULL, claimed_at INTEGER NOT NULL, PRIMARY KEY(user_id,day_index), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS game_stats (game TEXT PRIMARY KEY,total_plays INTEGER NOT NULL DEFAULT 0,total_wins INTEGER NOT NULL DEFAULT 0,total_wagered TEXT NOT NULL DEFAULT '0',total_payout TEXT NOT NULL DEFAULT '0',updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS user_game_stats (user_id TEXT NOT NULL,game TEXT NOT NULL,plays INTEGER NOT NULL DEFAULT 0,wins INTEGER NOT NULL DEFAULT 0,wagered TEXT NOT NULL DEFAULT '0',won TEXT NOT NULL DEFAULT '0',PRIMARY KEY(user_id,game),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS moderation_actions (id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id TEXT NOT NULL,target_user_id TEXT NOT NULL,action TEXT NOT NULL,reason TEXT,metadata TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS admin_actions (id INTEGER PRIMARY KEY AUTOINCREMENT,admin_id TEXT NOT NULL,command TEXT NOT NULL,target_id TEXT,details TEXT,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_daily_rewards_user ON daily_rewards(user_id,claimed_at DESC);
CREATE INDEX IF NOT EXISTS idx_game_stats_wins ON game_stats(total_wins DESC);
CREATE INDEX IF NOT EXISTS idx_user_game_stats_user ON user_game_stats(user_id,plays DESC);
CREATE INDEX IF NOT EXISTS idx_mod_actions_target ON moderation_actions(target_user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_admin_actions_admin ON admin_actions(admin_id,created_at DESC);
